package com.acme.worker

import java.net.{HttpURLConnection, URL, InetAddress, URI}
import java.util.{Base64, UUID}
import java.util.concurrent.{ConcurrentHashMap, Executors}
import javax.crypto.Mac
import javax.crypto.spec.SecretKeySpec
import scala.collection.mutable
import scala.util.{Try, Success, Failure}

object NtlmConstants {
  val NTLMSSP_NEGOTIATE = 1
  val NTLMSSP_CHALLENGE = 2
  val NTLMSSP_AUTH = 3
  val NEGOTIATE_NTLM = 0x00000200
  val NEGOTIATE_SIGN = 0x00000010
  val NEGOTIATE_SEAL = 0x00000020
  val NEGOTIATE_TARGET_INFO = 0x00800000
  val NEGOTIATE_128 = 0x20000000
  val NEGOTIATE_56 = 0x80000000
}

case class TenantConfig(
  tenantId: String,
  internalServiceUrl: String,
  ntlmDomain: String,
  serviceAccount: String,
  credentialHash: Array[Byte]
)

case class AuthContext(
  tenantId: String,
  sessionId: String,
  negotiateFlags: Int,
  serverChallenge: Array[Byte],
  authenticated: Boolean = false
)

trait CredentialProvider {
  def getNtlmHash(tenantId: String): Array[Byte]
  def getSessionKey(tenantId: String, challenge: Array[Byte]): Array[Byte]
}

class TenantCredentialStore extends CredentialProvider {
  private val tenantConfigs = new ConcurrentHashMap[String, TenantConfig]()

  def registerTenant(config: TenantConfig): Unit = {
    tenantConfigs.put(config.tenantId, config)
  }

  def getTenantConfig(tenantId: String): Option[TenantConfig] = {
    Option(tenantConfigs.get(tenantId))
  }

  override def getNtlmHash(tenantId: String): Array[Byte] = {
    Option(tenantConfigs.get(tenantId))
      .map(_.credentialHash)
      .getOrElse(throw new SecurityException(s"Unknown tenant: $tenantId"))
  }

  override def getSessionKey(tenantId: String, challenge: Array[Byte]): Array[Byte] = {
    val hash = getNtlmHash(tenantId)
    val mac = Mac.getInstance("HmacMD5")
    mac.init(new SecretKeySpec(hash, "HmacMD5"))
    mac.doFinal(challenge)
  }
}

class NtlmAuthHandler(credentialProvider: CredentialProvider) {
  private val activeSessions = new ConcurrentHashMap[String, AuthContext]()

  def initiateAuth(tenantId: String): (String, Array[Byte]) = {
    val sessionId = UUID.randomUUID().toString
    val negotiateMsg = buildNegotiateMessage(tenantId)
    val ctx = AuthContext(tenantId, sessionId, NtlmConstants.NEGOTIATE_NTLM, Array.empty)
    activeSessions.put(sessionId, ctx)
    (sessionId, negotiateMsg)
  }

  def handleChallenge(sessionId: String, challengeBytes: Array[Byte]): Array[Byte] = {
    val ctx = Option(activeSessions.get(sessionId))
      .getOrElse(throw new SecurityException("Invalid session"))
    val serverChallenge = extractServerChallenge(challengeBytes)
    val updatedCtx = ctx.copy(serverChallenge = serverChallenge)
    activeSessions.put(sessionId, updatedCtx)
    buildAuthenticateMessage(updatedCtx)
  }

  def resolveSession(sessionId: String): Option[AuthContext] = {
    Option(activeSessions.get(sessionId)).map(_.copy(authenticated = true))
  }

  private def buildNegotiateMessage(tenantId: String): Array[Byte] = {
    val flags = NtlmConstants.NEGOTIATE_NTLM | NtlmConstants.NEGOTIATE_SIGN |
      NtlmConstants.NEGOTIATE_SEAL | NtlmConstants.NEGOTIATE_128
    val header = "NTLMSSP\u0000".getBytes("UTF-8")
    header ++ intToBytes(NtlmConstants.NTLMSSP_NEGOTIATE) ++ intToBytes(flags)
  }

  private def buildAuthenticateMessage(ctx: AuthContext): Array[Byte] = {
    val sessionKey = credentialProvider.getSessionKey(ctx.tenantId, ctx.serverChallenge)
    val header = "NTLMSSP\u0000".getBytes("UTF-8")
    header ++ intToBytes(NtlmConstants.NTLMSSP_AUTH) ++ sessionKey
  }

  private def extractServerChallenge(data: Array[Byte]): Array[Byte] = {
    if (data.length >= 32) data.slice(24, 32)
    else throw new SecurityException("Invalid challenge message")
  }

  private def intToBytes(v: Int): Array[Byte] = {
    Array((v & 0xFF).toByte, ((v >> 8) & 0xFF).toByte,
      ((v >> 16) & 0xFF).toByte, ((v >> 24) & 0xFF).toByte)
  }
}

class BackgroundJobWorker(credentialStore: TenantCredentialStore) {
  private val authHandler = new NtlmAuthHandler(credentialStore)
  private val executor = Executors.newFixedThreadPool(4)
  private val jobResults = new ConcurrentHashMap[String, Any]()

  private val allowedHosts: Set[String] = Set(
    "internal-svc-alpha.corp",
    "internal-svc-beta.corp"
  )

  def submitJob(tenantId: String, targetResource: String): String = {
    val jobId = UUID.randomUUID().toString
    executor.submit(new Runnable {
      override def run(): Unit = {
        Try(executeWithNtlmAuth(tenantId, targetResource)) match {
          case Success(result) => jobResults.put(jobId, result)
          case Failure(ex) => jobResults.put(jobId, s"ERROR: ${ex.getMessage}")
        }
      }
    })
    jobId
  }

  private def executeWithNtlmAuth(tenantId: String, resource: String): String = {
    val resolvedUrl = resolveServiceEndpoint(tenantId, resource)
    val (sessionId, negotiateMsg) = authHandler.initiateAuth(tenantId)
    val conn = new URL(resolvedUrl).openConnection().asInstanceOf[HttpURLConnection]
    conn.setRequestMethod("GET")
    conn.setRequestProperty("Authorization",
      "NTLM " + Base64.getEncoder.encodeToString(negotiateMsg))
    conn.setInstanceFollowRedirects(false)
    val challengeHeader = conn.getHeaderField("WWW-Authenticate")
    if (challengeHeader == null || !challengeHeader.startsWith("NTLM ")) {
      throw new SecurityException("Server did not respond with NTLM challenge")
    }
    val challengeBytes = Base64.getDecoder.decode(challengeHeader.substring(5))
    val authMsg = authHandler.handleChallenge(sessionId, challengeBytes)
    val conn2 = new URL(resolvedUrl).openConnection().asInstanceOf[HttpURLConnection]
    conn2.setRequestMethod("GET")
    conn2.setRequestProperty("Authorization",
      "NTLM " + Base64.getEncoder.encodeToString(authMsg))
    val responseCode = conn2.getResponseCode
    if (responseCode == 200) {
      scala.io.Source.fromInputStream(conn2.getInputStream).mkString
    } else {
      throw new RuntimeException(s"Auth failed with status $responseCode")
    }
  }

  private def resolveServiceEndpoint(tenantId: String, resource: String): String = {
    val tenantConfig = credentialStore.getTenantConfig(tenantId)
      .getOrElse(throw new SecurityException(s"Unknown tenant: $tenantId"))
    val allowedBase = tenantConfig.internalServiceUrl
    val uri = new URI(resource)
    val resourceHost = uri.getHost
    val allowedUri = new URI(allowedBase)
    val allowedHost = allowedUri.getHost
    if (resourceHost == null || !resourceHost.equalsIgnoreCase(allowedHost)) {
      throw new SecurityException(
        s"Tenant $tenantId not authorized to access host: $resourceHost")
    }
    if (!allowedHosts.contains(resourceHost.toLowerCase)) {
      throw new SecurityException(s"Host not in allowlist: $resourceHost")
    }
    val scheme = uri.getScheme
    if (scheme == null || !scheme.equalsIgnoreCase("http")) {
      throw new SecurityException(s"Only HTTP scheme allowed, got: $scheme")
    }
    resource
  }
}

object WorkerApp extends App {
  val store = new TenantCredentialStore()
  store.registerTenant(TenantConfig(
    "tenant-alpha", "http://internal-svc-alpha.corp:8080",
    "CORP", "svc_alpha", Array.fill(16)(0x41.toByte)))
  store.registerTenant(TenantConfig(
    "tenant-beta", "http://internal-svc-beta.corp:8080",
    "CORP", "svc_beta", Array.fill(16)(0x42.toByte)))
  val worker = new BackgroundJobWorker(store)
  val jobId = worker.submitJob("tenant-alpha", "http://internal-svc-alpha.corp:8080/api/data")
  println(s"Job submitted: $jobId")
}
